// src/pages/StudentCandidates.jsx
import { useState } from "react";
import { useNavigate } from "react-router-dom";
import api from "../api";

export default function StudentCandidates() {
  const navigate = useNavigate();
  const [form, setForm] = useState({ name: "", party: "", position: "" });
  const [message, setMessage] = useState("");

  const handleChange = (e) => setForm({ ...form, [e.target.name]: e.target.value });

  const handleSubmit = async (e) => {
    e.preventDefault();
    setMessage("");
    try {
      const res = await api.post("/candidates", form);
      setMessage(res.data.message);
      setForm({ name: "", party: "", position: "" });
      // Optionally redirect
      // navigate("/student-dashboard");
    } catch (err) {
      setMessage(err.response?.data?.error || "Submission failed");
    }
  };

  return (
    <div style={{ minHeight: "100vh", backgroundColor: "#f4f6f8", padding: "40px", fontFamily: "Arial, sans-serif" }}>
      <header style={{ marginBottom: "30px", textAlign: "center" }}>
        <img src="/logo.png" alt="iVote Logo" style={{ height: "50px", marginBottom: "15px" }} />
        <h1 style={{ fontSize: "2rem", color: "#007bff", margin: 0 }}>Register Candidacy</h1>
        <p style={{ color: "#555" }}>Submit your requirements to apply as a candidate</p>
      </header>

      <form onSubmit={handleSubmit} style={{
        maxWidth: "500px",
        margin: "0 auto",
        display: "flex",
        flexDirection: "column",
        gap: "15px",
        background: "#fff",
        padding: "25px",
        borderRadius: "12px",
        boxShadow: "0 4px 12px rgba(0,0,0,0.08)"
      }}>
        <input
          name="name"
          placeholder="Candidate Name"
          value={form.name}
          onChange={handleChange}
          required
          style={{ padding: "10px", borderRadius: "8px", border: "1px solid #ccc" }}
        />
        <input
          name="party"
          placeholder="Party (optional)"
          value={form.party}
          onChange={handleChange}
          style={{ padding: "10px", borderRadius: "8px", border: "1px solid #ccc" }}
        />
        <input
          name="position"
          placeholder="Position"
          value={form.position}
          onChange={handleChange}
          required
          style={{ padding: "10px", borderRadius: "8px", border: "1px solid #ccc" }}
        />
        <button type="submit" style={{
          padding: "12px",
          borderRadius: "8px",
          border: "none",
          backgroundColor: "#007bff",
          color: "#fff",
          fontWeight: "bold",
          cursor: "pointer"
        }}>Submit</button>
        {message && <p style={{ textAlign: "center", color: message.includes("failed") ? "red" : "green" }}>{message}</p>}
      </form>
    </div>
  );
}
